SELECT COUNT(*) FROM votes as v, comments as c, postLinks as pl, postHistory as ph, users as u, posts as p WHERE u.Id = c.UserId AND p.Id = c.PostId AND p.Id = pl.PostId AND p.Id = ph.PostId AND u.Id = v.UserId AND c.Score=0 AND c.CreationDate>='2010-08-02 20:27:48'::timestamp AND c.CreationDate<='2014-09-10 16:09:23'::timestamp AND pl.CreationDate>='2011-11-03 05:09:35'::timestamp AND ph.PostHistoryTypeId=1;